mapper.codeEditorJavascript:
// ── Modul 3 · Eingangs-Guards ────────────────────────────────────────────
// Prueft die Pflichtfelder aus dem Vertriebler-Datensatz, bevor irgendein
// externer Call passiert. Faellt hier etwas durch, geht GATE 1 in den
// Fehlerpfad und es wird nichts geschrieben — insbesondere entsteht kein
// Lexware-Kontakt.

const s = (v) => (v === null || v === undefined) ? '' : String(v).trim();

const recordId = s(input.recordId);
const name     = s(input.name);
const strasse  = s(input.strasse);
const ort      = s(input.ort);
const plzRaw   = s(input.plz);
const best     = s(input.besteuerung);
// Airtable liefert Datumsfelder als ISO-String. Nur der Datumsteil wird
// gebraucht; die Zeitzone wuerde beim Zurueckschreiben den Vortag erzeugen.
const regelAb  = s(input.regelAb).slice(0, 10);

// PLZ: Airtable haelt eine Zahl -> fuehrende Null geht verloren (01067).
// plz5 ist die Form, die nach Lexware geht, plzInt nur die Plausipruefung.
const plzDigits = plzRaw.replace(/[^0-9]/g, '');
const plz5      = plzDigits ? plzDigits.padStart(5, '0') : '';
const plzInt    = plzDigits ? parseInt(plzDigits, 10) : 0;

// Hausnummer aus "Musterstrasse 12a" / "Musterstr. 12-14"
const hnMatch    = strasse.match(/(\d+\s*[a-zA-Z]?(?:\s*[-\/]\s*\d+\s*[a-zA-Z]?)?)\s*$/);
const hausnummer = hnMatch ? hnMatch[1].replace(/\s+/g, '') : '';

const missing = [];
if (!name)                        missing.push('Name');
if (!strasse)                     missing.push('Straße / Nr.');
if (strasse && !hausnummer)       missing.push('Hausnummer in Straße / Nr.');
if (!plz5)                        missing.push('Postleitzahl');
if (plz5 && (plzInt < 1 || plzInt > 99999)) missing.push('Postleitzahl (nicht 1-99999)');
if (!ort)                         missing.push('Ort');
if (!best)                        missing.push('Besteuerung');

// Bewusst als Praefix-Test statt zeichengenauem Vergleich: die Option heisst
// heute "Regelbesteuerung", und eine Umbenennung im Select soll hier nur den
// Hinweis kosten, nicht den Lauf.
const istRegel = /^regel/i.test(best);

// ⚙ Regelbesteuerung ab wird bei der Anlage auf das Anlagedatum gesetzt, wenn
// der Vertriebler regelbesteuert startet UND das Feld noch leer ist. Ein
// bereits gesetztes Datum bleibt unangetastet — es ist die genauere Angabe,
// weil der Wechsel nach §19 UStG zum Jahreswechsel greift und damit vor der
// Anlage liegen kann.
//
// heute kommt als fertiger YYYY-MM-DD-String aus Make (Organisations-
// Zeitzone). Bewusst NICHT new Date(): das rechnet in UTC und schoebe das
// Datum am Tagesrand um einen Tag — genau der Fallstrick, der am Stichtag
// die falsche Kondition trifft.
const heute        = s(input.heute).slice(0, 10);
const regelAbWrite = (istRegel && !regelAb && heute) ? heute : '';
const regelAbEff   = regelAb || regelAbWrite;

// Weiche Hinweise: sie blockieren NICHT. Der Vertriebler wird angelegt, die
// Zeile landet in der Status-Meldung an Operations.
const hinweise = [];
if (regelAbWrite) {
  hinweise.push('»⚙ Regelbesteuerung ab« war leer und wurde auf das Anlagedatum ' + regelAbWrite +
                ' gesetzt. Lag der Wechsel früher, bitte korrigieren — Umsätze mit einem ' +
                'Leistungsdatum davor lösen sonst als Kleinunternehmer auf und rechnen mit 0 %.');
} else if (istRegel && !regelAbEff) {
  hinweise.push('Besteuerung steht auf »' + best + '«, »⚙ Regelbesteuerung ab« ist leer und konnte ' +
                'nicht gesetzt werden (kein Anlagedatum übergeben) — bitte von Hand nachtragen.');
}

const ok = missing.length === 0;

// Lexware-Notiz: traegt den Besteuerungsstatus als Klartext mit. Der Status
// selbst bleibt Airtable-Wahrheit (pos-invoice liest ihn dort) — Lexware
// kennt am Kontakt keinen §19-Schalter, die Steuer sitzt an der Rechnung.
const noteLines = ['POS-Vertriebler · angelegt von Make'];
noteLines.push('Besteuerung: ' + (best || '—'));
if (regelAb) noteLines.push('Regelbesteuerung ab: ' + regelAb);

return {
  ok: ok,
  gate: ok ? 'go' : 'stop',
  reason: ok ? '' : 'Pflichtfelder fehlen oder sind unvollständig: ' + missing.join(', ') + '.',
  recordId: recordId,
  name: name,
  strasse: strasse,
  hausnummer: hausnummer,
  plz5: plz5,
  ort: ort,
  besteuerung: best,
  regelAb: regelAb,
  // Nur gefuellt, wenn wirklich geschrieben werden soll — Modul 13 filtert
  // darauf. Leer heisst: Feld nicht anfassen.
  regelAbWrite: regelAbWrite,
  // Der Wert, der nach dem Lauf im Feld steht (bestehend oder neu gesetzt).
  regelAbEff: regelAbEff,
  hinweise: hinweise.join(' '),
  note: noteLines.join(' · ')
};

// ctx als fertiger JSON-Text — eine Fehlermeldung kann Anfuehrungszeichen
// und Zeilenumbrueche tragen und wuerde den JSON-Body sonst zerlegen.
return { ctx: JSON.stringify({
  'Fehler': String(input.fehler || 'Rückschreiben nach Airtable fehlgeschlagen'),
  'Lexware ID': String(input.lexid || '')
}) };

// ── Modul 7 · Statuszeile Operations ─────────────────────────────────────
// Baut die Meldung fuers Operations-Topic. Kein Broadcast in einen
// City-Channel: ein Vertriebler ist keine oeffentliche Neuigkeit.

const parse = (v) => (typeof v === 'string' ? (v ? JSON.parse(v) : null) : v);

const g     = parse(input.g) || {};
const lexId = String(input.lexId || '');

const esc = (v) => String(v || '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const status = [
  '✅ <b>Vertriebler angelegt: ' + esc(g.name) + '</b>',
  esc(g.plz5 + ' ' + g.ort),
  'Lexware: ' + (lexId || '—') + ' (Lieferant)',
  'Besteuerung: ' + esc(g.besteuerung || '—')
];

if (String(g.regelAbEff || '') !== '') {
  status.push('Regelbesteuerung ab: ' + esc(g.regelAbEff) +
              (String(g.regelAbWrite || '') !== '' ? ' (Anlagedatum)' : ''));
}

// Konditionen haengen NICHT am Vertriebler, sondern werden ueber
// »Gültig für« gegen die Besteuerung aufgeloest. Ohne passende Version
// rechnet jeder Umsatz dieses Vertrieblers still mit Null.
status.push('📋 Prüfen, dass eine Konditionen-Version mit »Gültig für« = »' +
            esc(g.besteuerung || '—') + '« existiert — sonst rechnen die Umsätze mit Null.');

if (String(g.hinweise || '') !== '') {
  status.push('⚠️ ' + esc(String(g.hinweise)));
}

return { status: status.join('\n') };
